  "claim": {
    "component_id": "C027.component",
    "value": "Establishing that an identified approval occurred after placement leaves open whether another approval existed earlier.",
    "scope": "A limit on what supported lateness of one approval establishes; an earlier approval is neither established nor excluded.",
    "provenance": {
