      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly limits the lateness finding to the identified approval and preserves the possibility of another earlier approval."
    }
  },
  "signal_basis": {
    "component_id": "C027.signal_basis",
    "value": "Cross-checked records support a sequence showing that the identified approval occurred after order placement, distinguishing approval timing from documentation creation or upload timing.",
    "scope": "The identified approval for a particular order; this possible finding is assumed to occur for this assessment, rather than reported as already observed.",
